from lib import *
chapter(6,'maths','prime-time','Prime Time',
 ('The treasure box','A treasure box has two locks. One opens with a key of 12 and another with a key of 18. Which keys fit both? The answer lies in factors and multiples, the main characters of this chapter.'),
 [('Common multiples and common factors',['Multiples of 4 are 4, 8, 12, 16, and so on. Factors of 12 are the numbers that divide 12 exactly: 1, 2, 3, 4, 6, 12.','Common multiples of 4 and 6 include 12, 24, 36. The smallest is the least common multiple.','Common factors of 12 and 18 are 1, 2, 3 and 6. The largest is 6, the highest common factor.']),
  ('Prime numbers',['A prime number has exactly two factors: 1 and itself. 2, 3, 5, 7, 11 are prime.','A number with more than two factors is composite, like 12 or 15. The number 1 is neither prime nor composite.','2 is the only even prime. The Sieve of Eratosthenes finds primes: write 1 to 100, cross out multiples of 2, then 3, then 5, then 7. The numbers left are primes.']),
  ('Co-prime numbers',['Two numbers are co-prime if their only common factor is 1. For example 8 and 15 are co-prime, though neither is prime.','Co-prime numbers are useful for keeping things safe, such as in locks and codes.']),
  ('Prime factorisation',['Every composite number can be written as a product of primes. This is called its prime factorisation.','Use a factor tree: split 60 into 6 and 10, then 6 into 2 and 3, and 10 into 2 and 5. So 60 is 2 times 2 times 3 times 5.','The prime factorisation is the same however we split it.']),
  ('Divisibility tests',['A number is divisible by 2 if its last digit is even. By 5 if it ends in 0 or 5. By 10 if it ends in 0.','By 3 if the sum of its digits is divisible by 3. By 9 if the digit sum is divisible by 9.','By 4 if the last two digits form a number divisible by 4. By 6 if it is divisible by both 2 and 3.']),
  ('Fun with numbers',['Twin primes are primes that differ by 2, like 11 and 13.','Playing with primes shows that every number is built from them, like bricks.'])],
 [('Find the prime factorisation of 36.',[('36 equals 6 times 6.','Split into two factors.'),('6 is 2 times 3, so 36 is 2 times 2 times 3 times 3.','Split until all are prime.')]),
  ('Is 1,236 divisible by 3?',[('Digit sum is 1 plus 2 plus 3 plus 6 equals 12.','Add the digits.'),('12 is divisible by 3, so 1,236 is divisible by 3.','Rule of 3.')])],
 ('How would you explain why 2 is the only even prime?',['Every other even number is divisible by 2.','So it has at least three factors: 1, 2 and itself.'],['Thinking 1 is prime.','Thinking all odd numbers are prime.']),
 ['Factors divide a number. Multiples are found by multiplying.','Primes have exactly two factors.','Co-prime numbers share only the factor 1.','Every composite number has one prime factorisation.','Divisibility tests save time.'],
 [mcq('p5-1',1,'Which number is prime?','13',[('15','15 is divisible by 3 and 5.'),('21','21 is divisible by 3 and 7.')],'13 has only the factors 1 and 13.'),
  num('p5-2',1,'What is the HCF of 12 and 18?',6,'The common factors are 1, 2, 3, 6; the largest is 6.',[(2,'2 is common but not the greatest.')]),
  num('p5-3',1,'What is the LCM of 4 and 6?',12,'Multiples of 4: 4, 8, 12. Multiples of 6: 6, 12. First common is 12.',[(24,'24 is common but not the smallest.')]),
  tf('p5-4',1,'1 is a prime number.',False,'A prime needs exactly two factors; 1 has only one.'),
  mcq('p5-5',2,'The prime factorisation of 60 is','2 x 2 x 3 x 5',[('2 x 3 x 10','10 is not prime.'),('6 x 10','Neither 6 nor 10 is prime.')],'Keep splitting until every factor is prime.'),
  mcq('p5-6',2,'Which pair is co-prime?','8 and 15',[('6 and 9','They share the factor 3.'),('12 and 18','They share 6.')],'8 and 15 share only 1.'),
  mcq('p5-7',2,'A number is divisible by 3 if','its digit sum is divisible by 3',[('it ends in 3','Many multiples of 3, like 12, do not end in 3.'),('it is odd','6 is even but divisible by 3.')],'Add the digits and test.'),
  num('p5-8',2,'How many prime numbers are there from 1 to 10?',4,'2, 3, 5 and 7.',[(5,'1 is not prime.')]),
  mcq('p5-9',3,'Is 7,260 divisible by 4?','Yes, because 60 is divisible by 4',[('No, because it is even','Being even does not decide divisibility by 4.'),('No, because it ends in 0','Ending in 0 does not prevent it.')],'The last two digits 60 divide by 4.'),
  mcq('p5-10',3,'Twin primes are','primes that differ by 2',[('primes that are equal','Primes are different numbers.'),('two even primes','2 is the only even prime.')],'Like 11 and 13.')],
 keep=['prime','factor','multiple','HCF','LCM'])
